class Section:
    """A single config section that knows how to render itself."""

    def __init__(self, name, settings=None, sep='='):
        self.name = name
        self.settings = settings or {}
        self.sep = ' ' + sep + ' '

    def render(self):
        lines = [f'[{self.name}]']
        for key, val in self.settings.items():
            lines.append(f'{key}{self.sep}{val}')
        return '\n'.join(lines)


# Example usage
if __name__ == '__main__':
    general = Section('general', {'debug': 'true', 'retries': '3'}, ':')
    print(general.render())

    empty = Section('empty')
    print(empty.render())
